<?php
declare(strict_types=1);
const CONFIG_FILE='/var/www/vhosts/mamonestate.com/mamonestate-config.env';
function config(): array {$out=[];foreach(is_readable(CONFIG_FILE)?file(CONFIG_FILE,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES):[] as $line){if(str_contains($line,'=')&&!str_starts_with(trim($line),'#')){[$k,$v]=explode('=',$line,2);$out[trim($k)]=trim($v," \t\n\r\0\x0B\"'");}}return $out;}
function db(string $url): PDO {$x=parse_url($url);if(!$x)throw new RuntimeException('DATABASE_URL eksik');return new PDO(sprintf('pgsql:host=%s;port=%d;dbname=%s',$x['host'],$x['port']??5432,ltrim($x['path'],'/')),urldecode($x['user']??''),urldecode($x['pass']??''),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);}
$lock=fopen('/tmp/mamonestate-exchange-rates.lock','c');if(!$lock||!flock($lock,LOCK_EX|LOCK_NB)){fwrite(STDERR,"Kur güncellemesi zaten çalışıyor.\n");exit(0);}try{$cfg=config();$pdo=db($cfg['DATABASE_URL']??'');$ch=curl_init('https://open.er-api.com/v6/latest/TRY');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>30,CURLOPT_USERAGENT=>'MamonEstate/1.0']);$raw=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$data=json_decode((string)$raw,true);if($status!==200||($data['result']??'')!=='success'||($data['base_code']??'')!=='TRY')throw new RuntimeException('Kur sağlayıcısından geçerli veri alınamadı');$currencies=['TRY','EUR','USD','GBP','RUB','AED'];$rates=['TRY'=>1.0];foreach(array_slice($currencies,1) as $currency){$rate=(float)($data['rates'][$currency]??0);if($rate<=0)throw new RuntimeException($currency.' kuru eksik');$rates[$currency]=$rate;}$existing=[];foreach($pdo->query('select currency,rate from exchange_rates')->fetchAll(PDO::FETCH_ASSOC) as $row)$existing[$row['currency']]=(float)$row['rate'];foreach($rates as $currency=>$rate){if(isset($existing[$currency])&&$existing[$currency]>0){$change=abs($rate-$existing[$currency])/$existing[$currency];if($change>0.20)throw new RuntimeException($currency.' kurunda olağan dışı %'.round($change*100,1).' değişim');}}$providerTime=!empty($data['time_last_update_unix'])?date('c',(int)$data['time_last_update_unix']):null;$pdo->beginTransaction();$history=$pdo->prepare('insert into exchange_rate_history(currency,rate,provider,provider_updated_at) values(?,?,?,?::timestamptz)');$upsert=$pdo->prepare('insert into exchange_rates(currency,rate,updated_at) values(?,?,now()) on conflict(currency) do update set rate=excluded.rate,updated_at=now()');foreach($rates as $currency=>$rate){$history->execute([$currency,$rate,'ExchangeRate-API',$providerTime]);$upsert->execute([$currency,$rate]);}$pdo->commit();$asset="/var/www/vhosts/mamonestate.com/httpdocs/assets/js/rates-live.js";$tmp=$asset.".tmp";$javascript="window.MAMON_RATES=".json_encode($rates,JSON_UNESCAPED_SLASHES).";\n";if(file_put_contents($tmp,$javascript,LOCK_EX)===false||!rename($tmp,$asset))throw new RuntimeException("Ön yüz kur dosyası yazılamadı");echo date('c').' '.count($rates)." kur başarıyla güncellendi.\n";}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();fwrite(STDERR,date('c').' '.$e->getMessage()."\n");exit(1);}finally{flock($lock,LOCK_UN);fclose($lock);}
